  -- Includes functions outside app schemas; quoted identifiers and string bodies are inspected.
  IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE p.prokind IN('f','p') AND n.nspname NOT IN('pg_catalog','information_schema')
      AND NOT(n.nspname='public' AND p.proname=ANY(ARRAY['backfill_concert_program_review_identity','concert_cleanup_counts','concert_cleanup_foreign_keys','concert_cleanup_shared_dependency','concert_program_evidence_issue','decide_automatic_program_candidate','defer_automatic_program','delete_expired_concert','finish_automatic_program','plan_expired_concert_cleanup','program_auto_input_hash','program_candidate_snapshot_valid','program_confirmation_evidence_hash','protect_program_review_identity','queue_automatic_programs','record_concert_image_ocr','review_concert_program_candidate','review_concert_program_candidate_identity','save_concert_program_analysis','save_concert_program_analysis_v3','save_concert_program_analysis_v4','save_concert_program_rematch']))
      AND lower(replace(pg_get_functiondef(p.oid),'"','')) ~ token_pattern)
    THEN RAISE EXCEPTION 'OCR_RETIRE_BLOCKED_FUNCTION_REFERENCE'; END IF;
  IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE c.relkind IN('v','m') AND n.nspname NOT IN('pg_catalog','information_schema')
      AND NOT(n.nspname='public' AND c.relname='concert_program_candidate_status')
      AND lower(replace(pg_get_viewdef(c.oid,true),'"','')) ~ token_pattern)
    THEN RAISE EXCEPTION 'OCR_RETIRE_BLOCKED_VIEW_REFERENCE'; END IF;
  IF EXISTS(SELECT 1 FROM pg_constraint k WHERE k.contype='f'
    AND k.confrelid=ANY(ARRAY['public.concert_image_ocr_attempts'::regclass,'public.concert_image_ocr_results'::regclass,'public.concert_program_analyses'::regclass,'public.concert_program_candidates'::regclass,'public.concert_program_reviews'::regclass])
    AND NOT(k.conrelid=ANY(ARRAY['public.concert_image_ocr_attempts'::regclass,'public.concert_image_ocr_results'::regclass,'public.concert_program_analyses'::regclass,'public.concert_program_candidates'::regclass,'public.concert_program_reviews'::regclass])) )
    THEN RAISE EXCEPTION 'OCR_RETIRE_BLOCKED_INBOUND_FK'; END IF;
  IF EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid
    WHERE NOT t.tgisinternal AND p.proname=ANY(ARRAY['backfill_concert_program_review_identity','concert_cleanup_counts','concert_cleanup_foreign_keys','concert_cleanup_shared_dependency','concert_program_evidence_issue','decide_automatic_program_candidate','defer_automatic_program','delete_expired_concert','finish_automatic_program','plan_expired_concert_cleanup','program_auto_input_hash','program_candidate_snapshot_valid','program_confirmation_evidence_hash','protect_program_review_identity','queue_automatic_programs','record_concert_image_ocr','review_concert_program_candidate','review_concert_program_candidate_identity','save_concert_program_analysis','save_concert_program_analysis_v3','save_concert_program_analysis_v4','save_concert_program_rematch'])
      AND NOT(t.tgrelid='public.concert_program_reviews'::regclass AND t.tgname='program_review_identity_immutable'))
    THEN RAISE EXCEPTION 'OCR_RETIRE_BLOCKED_TRIGGER_REFERENCE'; END IF;
  IF EXISTS(SELECT 1 FROM pg_policy p WHERE coalesce(pg_get_expr(p.polqual,p.polrelid),'') ~ token_pattern
       OR coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') ~ token_pattern)
    THEN RAISE EXCEPTION 'OCR_RETIRE_BLOCKED_POLICY_REFERENCE'; END IF;
  -- Catch compiled dependencies (defaults/checks/policies/etc), in addition to
  -- the string-body reference check. Only the listed view/trigger/functions own them.
  IF EXISTS(SELECT 1 FROM pg_depend d WHERE d.refclassid='pg_proc'::regclass
    AND d.refobjid IN(SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=ANY(ARRAY['backfill_concert_program_review_identity','concert_cleanup_counts','concert_cleanup_foreign_keys','concert_cleanup_shared_dependency','concert_program_evidence_issue','decide_automatic_program_candidate','defer_automatic_program','delete_expired_concert','finish_automatic_program','plan_expired_concert_cleanup','program_auto_input_hash','program_candidate_snapshot_valid','program_confirmation_evidence_hash','protect_program_review_identity','queue_automatic_programs','record_concert_image_ocr','review_concert_program_candidate','review_concert_program_candidate_identity','save_concert_program_analysis','save_concert_program_analysis_v3','save_concert_program_analysis_v4','save_concert_program_rematch']))
    AND NOT(d.classid='pg_rewrite'::regclass AND d.objid IN(SELECT oid FROM pg_rewrite WHERE ev_class='public.concert_program_candidate_status'::regclass))
    AND NOT(d.classid='pg_trigger'::regclass AND d.objid IN(SELECT oid FROM pg_trigger WHERE tgrelid='public.concert_program_reviews'::regclass AND tgname='program_review_identity_immutable'))
    AND NOT(d.classid='pg_proc'::regclass AND d.objid IN(SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=ANY(ARRAY['backfill_concert_program_review_identity','concert_cleanup_counts','concert_cleanup_foreign_keys','concert_cleanup_shared_dependency','concert_program_evidence_issue','decide_automatic_program_candidate','defer_automatic_program','delete_expired_concert','finish_automatic_program','plan_expired_concert_cleanup','program_auto_input_hash','program_candidate_snapshot_valid','program_confirmation_evidence_hash','protect_program_review_identity','queue_automatic_programs','record_concert_image_ocr','review_concert_program_candidate','review_concert_program_candidate_identity','save_concert_program_analysis','save_concert_program_analysis_v3','save_concert_program_analysis_v4','save_concert_program_rematch']))))
    THEN RAISE EXCEPTION 'OCR_RETIRE_BLOCKED_COMPILED_DEPENDENCY'; END IF;
-- Row counts are recorded by preflight evidence; the retirement scope is all rows.
END
$retire_preflight$;


